let incident = msg.payload;
try {
    if (Buffer.isBuffer(incident)) incident = JSON.parse(incident.toString('utf8'));
    if (typeof incident === 'string') incident = JSON.parse(incident);
} catch (error) {
    node.warn(`Invalid SurvNG incident JSON: ${error.message}`);
    return null;
}

if (!incident || incident.type !== 'incident' || Number(incident.schema_version) !== 1) return null;
if (!['new', 'updated', 'complete'].includes(incident.state)) return null;
if (!incident.incident_id || !incident.camera_id || !incident.representative_event_id) return null;
const objects = Array.isArray(incident.objects) ? incident.objects : [];
if (incident.has_objects !== true && objects.length === 0) return null;

const internalOrigin = (env.get('SURVNG_INTERNAL_URL') || 'http://192.168.86.243:8088').replace(/\/$/, '');
const safeIncident = String(incident.incident_id).replace(/[^a-zA-Z0-9_-]/g, '_');
const revisionKey = `survng_notification_revision_${safeIncident}`;
const revision = Number(flow.get(revisionKey) || 0) + 1;
flow.set(revisionKey, revision);

msg.incident = incident;
msg.incidentRevision = revision;
msg.revisionKey = revisionKey;
msg.method = 'GET';
msg.url = internalOrigin + incident.snapshot_url;
msg.headers = { Accept: 'image/jpeg,image/*;q=0.9' };
delete msg.payload;
return msg;

const incident = msg.incident;
if (!incident || !Buffer.isBuffer(msg.payload)) return [null, null, null];

// Do not let a slower fetch from an older lifecycle revision overwrite a newer image.
if (Number(flow.get(msg.revisionKey) || 0) !== Number(msg.incidentRevision)) {
    return [null, null, null];
}

const cameraId = String(incident.camera_id);
const cameraSlug = cameraId.toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '') || 'camera';
const cameraName = String(incident.camera_name || cameraId);
const mqttPrefix = String(env.get('SURVNG_MQTT_PREFIX') || 'survng').replace(/^\/+|\/+$/g, '');
const discoveryPrefix = String(env.get('HA_MQTT_DISCOVERY_PREFIX') || 'homeassistant').replace(/^\/+|\/+$/g, '');
const imageTopic = `${mqttPrefix}/notifications/${cameraId}/image`;
const objectId = `survng_${cameraSlug}_incident`;
const imageEntityId = `image.${objectId}`;
const discoveryTopic = `${discoveryPrefix}/image/${objectId}/config`;
const discovery = {
    name: 'Incident Image',
    unique_id: `${objectId}_image`,
    default_entity_id: imageEntityId,
    image_topic: imageTopic,
    content_type: 'image/jpeg',
    availability_topic: `${mqttPrefix}/status`,
    availability_template: '{{ value_json.online }}',
    payload_available: 'True',
    payload_not_available: 'False',
    device: {
        identifiers: [`survng_${cameraId}`],
        name: cameraName,
        manufacturer: 'SurvNG',
        model: 'Network Camera'
    }
};

const discoveryMessage = {
    topic: discoveryTopic,
    payload: JSON.stringify(discovery),
    qos: 1,
    retain: true
};
const imageMessage = {
    topic: imageTopic,
    payload: msg.payload,
    qos: 1,
    retain: true
};

msg.notificationImage = `/api/image_proxy/${imageEntityId}`;
msg.imageEntityId = imageEntityId;
delete msg.payload;
delete msg.headers;
delete msg.method;
return [discoveryMessage, imageMessage, msg];

const incident = msg.incident;
if (!incident) return null;

// A slower snapshot request from an older lifecycle message must never replace a newer update.
if (Number(flow.get(msg.revisionKey) || 0) !== Number(msg.incidentRevision)) return null;

const notifyAction = env.get('SURVNG_NOTIFY_ACTION') || 'notify.mobile_app_CHANGE_ME';
const basePath = String(incident.incidents_url || '/survng/incidents').replace(/\/incidents\/?$/, '');
const startedMs = Date.parse(incident.started_at);
const at = Number.isFinite(startedMs) ? Math.floor(startedMs / 1000) : Math.floor(Date.now() / 1000);
const recordingUrl = `${basePath}/recordings?camera=${encodeURIComponent(incident.camera_id)}&at=${at}&source=main`;
const incidentsUrl = incident.incidents_url || `${basePath}/incidents`;
const camera = incident.camera_name || incident.camera_id;
const objects = Array.isArray(incident.objects) ? incident.objects : [];
const objectText = objects.length
    ? objects.map((item) => {
        const confidence = Number(item.confidence);
        const count = Number(item.count || 1);
        return `${count > 1 ? `${count}x ` : ''}${item.label}${confidence > 0 ? ` ${Math.round(confidence * 100)}%` : ''}`;
      }).join(', ')
    : 'motion';
const zones = Array.isArray(incident.zones) && incident.zones.length
    ? ` in ${incident.zones.join(', ')}`
    : '';
const eventCount = Number(incident.event_count || 1);
const duration = Math.max(0, Math.round(Number(incident.duration_seconds || 0)));
const phase = { new: 'Detected', updated: 'Updated', complete: 'Complete' }[incident.state] || 'Incident';
const timing = eventCount > 1
    ? `${eventCount} events${duration ? ` over ${duration}s` : ''}`
    : '1 event';

const notificationData = {
    tag: incident.incident_id,
    group: `survng_${incident.camera_id}`,
    alert_once: true,
    channel: 'SurvNG Incidents',
    color: '#0f9f8f',
    url: recordingUrl,
    clickAction: recordingUrl,
    actions: [
        { action: 'URI', title: 'View recording', uri: recordingUrl },
        { action: 'URI', title: 'All incidents', uri: incidentsUrl }
    ]
};
if (Number(msg.statusCode) >= 200 && Number(msg.statusCode) < 300 && msg.notificationImage) {
    notificationData.image = msg.notificationImage;
}

msg.payload = {
    action: notifyAction,
    data: {
        title: `${camera}: ${objectText}`,
        message: `${phase} ${objectText}${zones} · ${timing}`,
        data: notificationData
    }
};
return msg;
